import{_ as i,o as t,c as s,a2 as o}from"./chunks/framework.DeW-aKVm.js";const u=JSON.parse('{"title":"k3sctl","description":"Declarative lifecycle management for K3s clusters over SSH — install, upgrade, reconfigure, back up, and reset from one YAML file.","frontmatter":{"title":"k3sctl","description":"Declarative lifecycle management for K3s clusters over SSH — install, upgrade, reconfigure, back up, and reset from one YAML file.","section":"k3sctl","docType":"overview","outline":"deep"},"headers":[],"relativePath":"docs/k3sctl/index.md","filePath":"docs/k3sctl/index.md"}'),a={name:"docs/k3sctl/index.md"};function n(l,e,r,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="k3sctl" tabindex="-1">k3sctl <a class="header-anchor" href="#k3sctl" aria-label="Permalink to &quot;k3sctl&quot;">​</a></h1><p><code>k3sctl</code> is a declarative lifecycle management tool for <a href="https://k3s.io" target="_blank" rel="noreferrer">K3s</a> clusters, created and inspired by <a href="https://github.com/k0sproject/k0sctl" target="_blank" rel="noreferrer">k0sctl</a>. Point it at a YAML file describing your hosts and it installs, upgrades, reconfigures, backs up, and resets the cluster over SSH.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k3sctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent-address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0.2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3sctl.yaml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR k3sctl.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k3sctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3sctl.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k3sctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubeconfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubeconfig.yaml</span></span></code></pre></div><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li>Declarative cluster configuration with servers and agents in one file.</li><li>Installs and upgrades K3s binaries from GitHub releases, a URL, a local file, or an existing installation on the host.</li><li>Generates server and agent configuration plus systemd units.</li><li>Supports labels, taints, extra install flags, environment variables, and arbitrary file uploads.</li><li>Applies additional Kubernetes manifests bundled in the configuration file.</li><li>Automated etcd snapshots with S3 upload, retention, and pruning, plus etcd member validation and restore from a snapshot.</li><li>Fetches a ready-to-use admin kubeconfig.</li><li>Idempotent <code>apply</code>: safe to re-run, and only changes what drifted.</li><li>Rolling upgrades with drain and cordon for both servers and agents.</li><li>Configuration validation (<code>config validate</code>) and diff (<code>config diff</code>).</li><li>Air-gap install: upload pre-downloaded image bundles for offline clusters.</li><li>Dry-run mode with <code>--dry-run</code>.</li><li>Private registry mirrors and authentication (<code>registries</code>).</li><li>Secrets encryption at rest with key rotation and re-encryption (<code>secretsEncrypt</code>).</li><li>Certificate Authority rotation (<code>certRotate.rotateCA</code>).</li><li>Cluster join token rotation (<code>token.rotate</code>).</li><li>Post-apply cluster health verification (<code>healthCheck</code>).</li><li>Pre-flight checks for cgroups, kernel modules, ports, and disk (<code>preflight</code>).</li><li>Declarative networking: cluster/service CIDRs, DNS, flannel backend, egress selector mode, NodePort range, and ServiceLB namespace (<code>network</code>).</li><li>Component disabling: turn off packaged components like traefik, servicelb, metrics-server, and individual subsystems like kube-proxy or the Helm controller (<code>disable</code>).</li><li>TLS SAN management: add Subject Alternative Names to the API server certificate (<code>tls</code>).</li><li>Kubeconfig output control: file mode, group, and cluster name (<code>kubeconfig</code>).</li><li>External datastore: MySQL, PostgreSQL, or etcd endpoint with TLS (<code>datastore</code>).</li><li>API server listener: advertise address/port, bind address, HTTPS port (<code>server</code>).</li><li>Security hardening: SELinux, kernel defaults protection, and encryption provider selection (<code>security</code>).</li><li>Typed component arguments: pass arguments directly to kube-apiserver, kube-controller-manager, kubelet, kube-proxy, etcd, and others (<code>componentArgs</code>).</li><li>Container runtime: system default registry, pause image, snapshotter, default runtime override, and custom resolv.conf (<code>runtime</code>).</li><li>Embedded container registry: enable the K3s built-in Spegel distributed registry (<code>embeddedRegistry</code>).</li><li>Image credential provider: external kubelet credential plugin for pulling images from private registries (<code>imageCredentialProvider</code>).</li><li>Per-host node networking: external IPs, internal/external DNS names for multi-homed and cloud nodes (<code>nodeExternalIP</code>, <code>nodeInternalDNS</code>, <code>nodeExternalDNS</code>).</li><li>Local storage: custom path for the built-in local-path provisioner (<code>localStorage</code>).</li><li>Advanced etcd tuning: expose metrics, disable automatic snapshots, snapshot naming, and reconcile interval (<code>etcdAdvanced</code>).</li><li>Advanced flannel options: interface selection, custom flannel and CNI configuration file paths (<code>network.flannelIface</code>, <code>flannelConf</code>, <code>flannelCNIConf</code>).</li><li>Advanced S3 snapshot storage: session tokens, bucket lookup type, proxy, config secret, timeout, and per-S3 retention (<code>etcdSnapshots.s3</code>).</li><li>Token files: read server and agent tokens from files instead of inline values (<code>token.tokenFile</code>, <code>token.agentTokenFile</code>).</li><li>Kubeconfig output path: write the kubeconfig to a custom location (<code>kubeconfig.path</code>).</li><li>Supervisor metrics and pprof: expose the supervisor metrics and profiling endpoints (<code>server.supervisorMetrics</code>, <code>server.enablePprof</code>).</li><li>Rootless mode: run K3s without root privileges, and prefer bundled binaries over host-installed versions (<code>security.rootless</code>, <code>security.preferBundledBin</code>).</li><li>CRI endpoint override: point K3s at a custom container runtime or image service socket (<code>runtime.containerRuntimeEndpoint</code>, <code>runtime.imageServiceEndpoint</code>).</li><li>Registry endpoint control: disable the default network endpoint for the embedded Spegel registry (<code>embeddedRegistry.disableDefaultRegistryEndpoint</code>).</li><li>Agent load balancer port: configure the port the agent uses to reach the control plane (<code>agent.lbServerPort</code>).</li><li>Per-host node ID: append the machine ID to the node name for uniqueness in auto-scaled or cloned environments (<code>withNodeID</code>).</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Linux hosts only. <code>k3sctl</code> drives the cluster over SSH, so each host must be reachable and must provide <code>sudo</code> or a root login.</p></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><code>k3sctl</code> reads the <code>Cluster</code> document from your config file.</li><li>It connects to each host over SSH and detects the OS and architecture.</li><li>It uploads or downloads the requested K3s version, writes the server or agent configuration and the systemd unit, then starts K3s.</li><li>Once the API server answers, it applies any additional manifests found in the same file with <code>kubectl apply</code>.</li><li><code>k3sctl kubeconfig</code> reads the admin kubeconfig back so you can use it locally.</li></ol><p>Because the desired state is the file, re-running <code>apply</code> after editing it is the normal way to change a cluster.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Linux hosts for servers and agents.</li><li>SSH access, with a key or the agent available to <code>k3sctl</code>.</li><li>Root or passwordless <code>sudo</code> on each host.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./installation">Installation</a>: release binary, <code>go install</code>, or build from source.</li><li><a href="./configuration">Configuration</a>: every host, K3s, and drain option.</li><li><a href="./commands">Commands</a>: the full CLI and the flags accepted by <code>apply</code>.</li></ul>`,13)])])}const k=i(a,[["render",n]]);export{u as __pageData,k as default};
